class HDC2021_Simulator(BaseVirtualSensor):
    REG_WIDTH = 8

    def __init__(self):
        super().__init__()
        self.regs = {
            0x00: 0x00,  # TEMP_LOW
            0x01: 0x00,  # TEMP_HIGH
            0x02: 0x00,  # HUM_LOW
            0x03: 0x00,  # HUM_HIGH
            0x04: 0x00,  # STATUS
            0x05: 0x00,  # TEMP_MAX
            0x06: 0x00,  # HUM_MAX
            0x07: 0x00,  # INTERRUPT_ENABLE
            0x08: 0x00,  # TEMP_OFFSET
            0x09: 0x00,  # HUM_OFFSET
            0x0A: 0x01,  # TEMP_THR_L
            0x0B: 0xFF,  # TEMP_THR_H
            0x0C: 0x00,  # RH_THR_L
            0x0D: 0xFF,  # RH_THR_H
            0x0E: 0x00,  # DEVICE_CONFIG
            0x0F: 0x00,  # MEAS_CONFIG
            0xFC: 0x49,  # MANUF_ID_L
            0xFD: 0x54,  # MANUF_ID_H
            0xFE: 0xD0,  # DEVICE_ID_L
            0xFF: 0x07   # DEVICE_ID_H
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:#04x}")

        value = self.regs[addr]
        if nbytes == 1:
            return (value >> 8) & 0xFF
        elif nbytes == 2:
            return value
        else:
            raise ValueError("nbytes must be 1 or 2")

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:#04x}")

        if nbytes == 1:
            current_value = self.regs[addr]
            data = (current_value & 0xFF) | (data << 8)

        if addr == 0x0E and (data & 0x80):
            # Soft reset
            for reg_addr in self.regs:
                self.regs[reg_addr] = self.regs[reg_addr] & 0x7F

        if addr != 0x0E:
            self.regs[addr] = data

